import json
from src.nodes.base import BaseNode
from src.runtime.assets.suitability import (
    get_asset_suitability_engine,
    SuitabilityRequest,
)

class Hou_Mcp_Asset_Ranking(BaseNode):
    name = "hou_mcp_asset_ranking"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("candidates_json",     "string", widget_type="text", default="[]")
        self.add_input("environment",         "string", widget_type="text", default="western_room")
        self.add_input("role",                "string", widget_type="text", default="")
        self.add_input("placement_context",   "string", widget_type="text", default="")
        self.add_output("selected_asset_json","string")
        self.add_output("selected_name",      "string")
        self.add_output("final_score",        "float")
        self.add_output("ranked_json",        "string")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        raw = (inputs.get("candidates_json") or "").strip()
        environment = (inputs.get("environment") or "").strip()
        role = (inputs.get("role") or "").strip()
        placement_context = (inputs.get("placement_context") or "").strip()

        if not environment:
            self.log_error("No environment provided.")
            return {"selected_asset_json": "{}", "selected_name": "", "final_score": 0.0, "ranked_json": "[]", "exec_out": True}

        try:
            candidates = json.loads(raw) if raw else []
        except Exception:
            self.log_error("candidates_json is not valid JSON.")
            return {"selected_asset_json": "{}", "selected_name": "", "final_score": 0.0, "ranked_json": "[]", "exec_out": True}

        try:
            eng = get_asset_suitability_engine()
            req = SuitabilityRequest(
                environment=environment,
                role=role,
                placement_context=placement_context,
            )
            result = eng.rank_assets(candidates, req)

            if result.best:
                best_idx = next(
                    (i for i, c in enumerate(candidates)
                     if str(c.get("asset_id", c.get("name", ""))) == result.best.asset_id),
                    0,
                )
                selected_json = json.dumps(candidates[best_idx], sort_keys=True)
                selected_name = result.best.asset_name
                final_score = result.best.final_score
            else:
                selected_json, selected_name, final_score = "{}", "", 0.0

            ranked_json = json.dumps([s.to_dict() for s in result.scores], sort_keys=True, indent=2)
            self.log_info(
                f"Ranked {result.total_candidates} candidates for '{environment}/{role}'. "
                f"Best: '{selected_name}' ({final_score:.2f}). "
                f"Rejected: {result.rejected_count}."
            )
            return {
                "selected_asset_json": selected_json,
                "selected_name": selected_name,
                "final_score": final_score,
                "ranked_json": ranked_json,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Asset ranking failed: {exc}")
            return {"selected_asset_json": "{}", "selected_name": "", "final_score": 0.0, "ranked_json": "[]", "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Ranking
